import math

def simpangan_baku(data, sampel=False):
    n = len(data)
    if sampel and n < 2:
        return None
    m = sum(data) / n
    pembagi = n - 1 if sampel else n
    return round(math.sqrt(sum((x - m) ** 2 for x in data) / pembagi), 4)

