def kuartil_iqr(data):
    s = sorted(data)

    def kuantil(q):
        p = (len(s) - 1) * q
        lo = int(p)
        hi = min(lo + 1, len(s) - 1)
        return s[lo] + (s[hi] - s[lo]) * (p - lo)

    q1, q3 = kuantil(0.25), kuantil(0.75)
    return (q1, q3, q3 - q1)

def mad(data):
    def med(v):
        s = sorted(v)
        n = len(s)
        return s[n // 2] if n % 2 else (s[n // 2 - 1] + s[n // 2]) / 2

    m = med(data)
    return med([abs(x - m) for x in data])

def pencilan_iqr(data):
    s = sorted(data)

    def kuantil(q):
        p = (len(s) - 1) * q
        lo = int(p)
        hi = min(lo + 1, len(s) - 1)
        return s[lo] + (s[hi] - s[lo]) * (p - lo)

    q1, q3 = kuantil(0.25), kuantil(0.75)
    iqr = q3 - q1
    return [x for x in s if x < q1 - 1.5 * iqr or x > q3 + 1.5 * iqr]

def ringkasan_lima(data):
    s = sorted(data)

    def kuantil(q):
        p = (len(s) - 1) * q
        lo = int(p)
        hi = min(lo + 1, len(s) - 1)
        return s[lo] + (s[hi] - s[lo]) * (p - lo)

    return (s[0], kuantil(0.25), kuantil(0.5), kuantil(0.75), s[-1])

