import statistics

def koefisien_variasi(data):
    m = statistics.mean(data)
    if m == 0:
        return None
    return round(statistics.stdev(data) / m, 4)

def minmax(data):
    lo, hi = min(data), max(data)
    if hi == lo:
        return [0.0 for _ in data]
    return [round((x - lo) / (hi - lo), 4) for x in data]

