def proporsi_dalam(data, k):
    n = len(data)
    m = sum(data) / n
    s = (sum((x - m) ** 2 for x in data) / n) ** 0.5
    dalam = sum(1 for x in data if abs(x - m) <= k * s)
    return round(dalam / n, 4)
